class Solution:
    def circularGameLosers(self, n: int, k: int) -> list[int]:
        visited = set()
        curr = 0
        i = 1
        while curr not in visited:
            visited.add(curr)
            curr = (curr + i * k) % n
            i += 1
        return [p + 1 for p in range(n) if p not in visited]

class Solution {
public:
    std::vector<int> circularGameLosers(int n, int k) {
        std::vector<bool> visited(n, false);
        int curr = 0, step = 1;
        while (!visited[curr]) {
            visited[curr] = true;
            curr = (curr + step * k) % n;
            step++;
        }
        std::vector<int> losers;
        for (int p = 0; p < n; p++) {
            if (!visited[p]) losers.push_back(p + 1);
        }
        return losers;
    }
};

class Solution {
    public int[] circularGameLosers(int n, int k) {
        boolean[] visited = new boolean[n];
        int curr = 0, step = 1;
        while (!visited[curr]) {
            visited[curr] = true;
            curr = (curr + step * k) % n;
            step++;
        }
        List<Integer> losers = new ArrayList<>();
        for (int p = 0; p < n; p++) {
            if (!visited[p]) losers.add(p + 1);
        }
        int[] ans = new int[losers.size()];
        for (int i = 0; i < losers.size(); i++) ans[i] = losers.get(i);
        return ans;
    }
}

